<script setup>
import {ref,onMounted} from 'vue';import PageHeader from '../../components/common/PageHeader.vue';import OrderProgress from '../../components/common/OrderProgress.vue';import StatusView from '../../components/common/StatusView.vue';import {getOrders} from '../../api/orders.js'
const orders=ref([]),loading=ref(true);onMounted(async()=>{orders.value=(await getOrders()).data.items;loading.value=false});const statusClass=x=>x==='已完成'?'success':'progress'
</script>
<template><div class="page-shell"><div class="container"><PageHeader title="我的定制" :breadcrumbs="['首页','我的定制']"><el-button type="primary" @click="$router.push('/customize')">新建定制需求</el-button></PageHeader><StatusView v-if="loading" type="loading"/><div v-else class="content-columns"><div><section v-if="orders[0]" class="active-order"><div class="section-head"><h2>当前定制（进行中）</h2><span>预计送达：{{orders[0].delivery}}</span></div><div class="active-summary"><img :src="orders[0].image"><div><b>订单号：{{orders[0].id}}</b><h3>{{orders[0].name}}</h3><OrderProgress :steps="orders[0].progress" :current="orders[0].current"/></div></div><div class="next-action"><span><b>下一步：</b>设计师正在深化方案，请留意方案确认通知。</span><el-button plain @click="$router.push(`/orders/${orders[0].id}`)">查看进度</el-button></div></section><section class="table-section orders-table"><div class="table-section__head"><h2>我的定制订单</h2><router-link to="/orders" class="text-link">查看全部</router-link></div><el-table :data="orders"><el-table-column prop="id" label="订单号" min-width="150"/><el-table-column prop="name" label="项目名称" min-width="180"/><el-table-column prop="createdAt" label="创建日期" width="120"/><el-table-column label="当前阶段" width="120"><template #default="{row}"><span :class="['status-dot',statusClass(row.status)]"></span>{{row.stage}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><router-link class="text-link" :to="`/orders/${row.id}`">查看详情</router-link></template></el-table-column></el-table></section></div><aside class="aside-stack"><section class="aside-section"><h3>专属服务</h3><div class="advisor"><div class="avatar">林</div><div><b>林设计师</b><span>专属家居顾问</span></div></div><p class="muted">工作时间：9:00–18:00</p><el-button plain style="width:100%">联系设计师</el-button></section><section class="aside-section"><div class="aside-title"><h3>最新设计方案</h3><router-link :to="`/schemes/${orders[0]?.id}`">查看</router-link></div><img class="scheme-image" :src="orders[0]?.image"><b>{{orders[0]?.name}}</b></section><section class="aside-section assistant-entry"><h3>AI 定制助手</h3><p>解答材料、流程和空间规划问题。</p><el-button type="primary" plain style="width:100%" @click="$router.push('/assistant')">开始咨询</el-button></section></aside></div></div></div></template>
<style scoped>.active-order{background:#fff;border:1px solid #c99474;padding:20px;margin-bottom:18px}.section-head,.aside-title{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--c-border);padding-bottom:12px}.section-head h2,.table-section h2,.aside-section h3{font:500 18px var(--font-display);margin:0}.section-head span{color:var(--c-muted)}.active-summary{display:grid;grid-template-columns:190px 1fr;gap:22px;padding:20px 0}.active-summary>img{height:150px}.active-summary h3{font:500 18px var(--font-display);margin:8px 0}.next-action{display:flex;align-items:center;justify-content:space-between;padding:12px 14px;background:#f7f3ed}.advisor{display:flex;align-items:center;gap:12px;margin:18px 0}.avatar{width:44px;height:44px;border-radius:50%;display:grid;place-items:center;background:var(--c-soft);font-family:var(--font-display);font-size:18px}.advisor span{display:block;color:var(--c-muted)}.scheme-image{height:145px;margin:14px 0 10px}.assistant-entry p{color:var(--c-muted)}@media(max-width:650px){.active-summary{grid-template-columns:1fr}.active-summary>img{height:210px}.next-action{align-items:flex-start;gap:12px;flex-direction:column}.section-head{align-items:flex-start;gap:8px;flex-direction:column}}</style>
